 head+=f'''<button class="study-entry {kind}" data-target="{target}"><img class="paper" src="assets/paper-{'blue' if kind=='audio' else 'ivory'}.png" alt=""><img class="paper-detail" src="assets/paper-grid.png" alt=""><img class="object" src="assets/{img}.png" alt=""><strong class="entry-label">{title}</strong><span class="subtitle">{sub}</span><span class="count"></span><img class="entry-arrow" src="../article-reader/assets/arrow-right.svg" alt=""></button>'''
