# Main current compare URL also exposes the new study without losing old archives.
(o/'preview.html').write_text('''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>原创剧场更新预览</title><link rel="icon" href="data:,"><link rel="stylesheet" href="gallery.css"></head><body><header><h1>原创剧场 A / 相片拼贴与琥珀胶片</h1><p><a href="../material-study/preview.html">打开学习天地三方案与两页完整对比</a></p></header><main class="gallery"><section><h2>调整前</h2><iframe src="before-material.html" title="调整前"></iframe></section><section><h2>当前 A 方案</h2><iframe src="index.html" title="当前 A 方案"></iframe></section></main></body></html>''',encoding='utf-8')
